//! Diesel's table DSL. In a real project this file is generated by
//! `diesel print-schema` from the live database; it is checked in here so the
//! benchmark builds without a database connection.

diesel::table! {
    users (id) {
        id -> Int4,
        email -> Text,
        username -> Text,
        created_at -> Timestamptz,
    }
}

diesel::table! {
    posts (id) {
        id -> Int4,
        user_id -> Int4,
        title -> Text,
        content -> Text,
        views -> Int4,
        created_at -> Timestamptz,
    }
}

diesel::joinable!(posts -> users (user_id));
diesel::allow_tables_to_appear_in_same_query!(users, posts);
